import { test } from "node:test";
import assert from "node:assert/strict";
import { loadConfig } from "../src/config/load.ts";
import { DEFAULTS } from "../src/config/defaults.ts";
import { quoteFare } from "../src/rides/fare.ts";
import { pickDriver, type Driver } from "../src/rides/matching.ts";

const lisbonFile = { city: "lisbon", pricing: { surgeCap: 3 }, dispatch: { searchRadiusKm: 8 } };

test("with no file and no environment, the defaults are used", () => {
    assert.deepEqual(loadConfig({}), DEFAULTS);
});

test("environment variables are typed like the setting they override", () => {
    const config = loadConfig({ RIDES__CITY: "porto", RIDES__FEATURES__SCHEDULED_RIDES: "true", PATH: "/usr/bin" });
    assert.equal(config.city, "porto");
    assert.equal(config.features.scheduledRides, true);
    assert.throws(() => loadConfig({ RIDES__FEATURES__SCHEDULED_RIDES: "yes" }), /must be true or false/);
    assert.throws(() => loadConfig({ RIDES__PRICING__SURGECAP: "2" }), /unknown setting RIDES__PRICING__SURGECAP/);
});

test("a city file that sets one pricing value keeps the other pricing defaults", () => {
    let config;
    try {
        config = loadConfig({}, lisbonFile);
    } catch (err) {
        console.log("loadConfig with the Lisbon file threw:", (err as Error).message);
        throw err;
    }
    assert.deepEqual(config.pricing, { ...DEFAULTS.pricing, surgeCap: 3 });
    assert.deepEqual(config.dispatch, { ...DEFAULTS.dispatch, searchRadiusKm: 8 });
});

test("an environment variable beats the city file for that one key only", () => {
    const config = loadConfig({ RIDES__PRICING__SURGE_CAP: "2.5", RIDES__PRICING__PER_KM_CENTS: "95" }, lisbonFile);
    assert.deepEqual(config.pricing, { ...DEFAULTS.pricing, surgeCap: 2.5, perKmCents: 95 });
    assert.equal(config.dispatch.searchRadiusKm, 8);
    assert.equal(config.city, "lisbon");
});

test("loading never changes the built-in defaults", () => {
    try {
        loadConfig({ RIDES__DISPATCH__MAX_ETA_MINUTES: "20" }, lisbonFile);
    } catch {
        // only the defaults matter here
    }
    assert.equal(DEFAULTS.pricing.surgeCap, 2);
    assert.equal(DEFAULTS.dispatch.searchRadiusKm, 5);
    assert.equal(DEFAULTS.dispatch.maxEtaMinutes, 12);
});

test("fares in Lisbon use the city's surge cap and the default rates", () => {
    const { pricing } = loadConfig({}, lisbonFile);
    const quote = quoteFare(pricing, { distanceKm: 10, minutes: 20, surge: 4 });
    assert.deepEqual(quote, { currency: "EUR", amountCents: 5550, surgeApplied: 3 });
});

test("dispatch combines the city's radius with vehicle classes from the environment", () => {
    const { dispatch } = loadConfig({ RIDES__DISPATCH__VEHICLE_CLASSES: "standard, xl, tuk-tuk" }, lisbonFile);
    const drivers: Driver[] = [
        { id: "d1", vehicleClass: "tuk-tuk", distanceKm: 7, etaMinutes: 9 },
        { id: "d2", vehicleClass: "tuk-tuk", distanceKm: 9, etaMinutes: 6 },
        { id: "d3", vehicleClass: "standard", distanceKm: 1, etaMinutes: 2 },
    ];
    assert.equal(pickDriver(dispatch, drivers, "tuk-tuk")?.id, "d1");
    assert.equal(dispatch.maxEtaMinutes, 12);
});
